#!/usr/bin/env bash\nset -euo pipefail\n\n# Determine the datetime to use. If MOCK_DATE is set, use it; otherwise use the current system time.\nif [[ -n "${MOCK_DATE:-}" ]]; then\n  datetime="${MOCK_DATE}"\nelse\n  datetime="$(date '+%Y-%m-%d %H:%M')"\nfi\n\n# Extract the hour component (00-23). Use GNU date if available; fall back to BSD date syntax.\nif date -d "$datetime" '+%H' >/dev/null 2>&1; then\n  hour=$(date -d "$datetime" '+%H')\nelse\n  # BSD/macOS date format\n  hour=$(date -j -f "%Y-%m-%d %H:%M" "$datetime" '+%H')\nfi\n\n# Choose the appropriate emoji based on the hour.\nif (( hour < 6 )); then\n  emoji="🌅"\nelif (( hour < 18 )); then\n  emoji="☀️"\nelse\n  emoji="🌙"\nfi\n\n# Output the timestamp followed by the emoji.\necho "$datetime $emoji"\n
